{
  "title": "Swagger Petstore - Sample",
  "version": "1.0.0",
  "description": "A minimal Petstore-style sample spec used for local development and testing."
}

{
  "operationId": "listPets",
  "summary": "List all pets",
  "tags": [
    "pets"
  ],
  "security": [],
  "parameters": [
    {
      "name": "limit",
      "in": "query",
      "required": false,
      "schema": {
        "type": "integer",
        "default": 20
      },
      "description": "Maximum number of pets to return"
    }
  ],
  "responses": {
    "200": {
      "description": "A paged array of pets",
      "content": {
        "application/json": {
          "schema": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/Pet"
            }
          }
        }
      }
    },
    "400": {
      "description": "Invalid request",
      "content": {
        "application/json": {
          "schema": {
            "$ref": "#/components/schemas/Error"
          }
        }
      }
    }
  }
}

{
  "get": {
    "operationId": "getPetById",
    "summary": "Get a pet by ID",
    "tags": [
      "pets"
    ],
    "security": [],
    "parameters": [
      {
        "name": "petId",
        "in": "path",
        "required": true,
        "schema": {
          "type": "integer"
        }
      }
    ],
    "responses": {
      "200": {
        "description": "The requested pet",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Pet"
            }
          }
        }
      },
      "404": {
        "description": "Pet not found",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      }
    }
  },
  "delete": {
    "operationId": "deletePet",
    "summary": "Delete a pet",
    "tags": [
      "pets"
    ],
    "parameters": [
      {
        "name": "petId",
        "in": "path",
        "required": true,
        "schema": {
          "type": "integer"
        }
      }
    ],
    "responses": {
      "204": {
        "description": "Pet deleted"
      },
      "404": {
        "description": "Pet not found"
      },
      "401": {
        "description": "Unauthorized"
      }
    }
  }
}
